import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import { Refresh } from '@mui/icons-material';

const Awards = () => {
  const [awardsData, setAwardsData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [imageLoadingStates, setImageLoadingStates] = useState({});

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isTablet = useMediaQuery(theme.breakpoints.down('md'));

  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbzbekTZSbZAZcdiLw8ROMQrQG4h5mf8IDYpZr0GqGQhi-9KE-ovuA1TeQvrtNQ2kbQ_UA/exec';

  const fetchAwardsData = async () => {
    setLoading(true);
    setError(null);
    try {
      console.log('Fetching awards data...');
      const response = await fetch(`${SCRIPT_URL}?t=${Date.now()}`);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const result = await response.json();
      console.log('API Response:', result);
      
      if (result.success && result.data) {
        const transformedData = result.data.map((item, index) => ({
          imageNo: item.imageNo ?? index + 1,
          fileName: item.fileName || `Award ${item.imageNo ?? index + 1}`,
          thumbnailUrl: item.thumbnailUrl,
          previewUrl: item.previewUrl,
          description: item.description || ''
        }));
        
        console.log('Transformed data:', transformedData);
        setAwardsData(transformedData);
        
        const initialLoadingStates = {};
        transformedData.forEach((item, index) => {
          initialLoadingStates[index] = true;
        });
        setImageLoadingStates(initialLoadingStates);
      } else {
        throw new Error(result.error || 'No data received from server');
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setError(`Error loading awards: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Use preview URL directly - it's more reliable than thumbnail URLs
  const getImageUrl = (item) => {
    // Always prefer previewUrl as it's a direct download link
    if (item.previewUrl && item.previewUrl.includes('uc?id=')) {
      return item.previewUrl;
    }
    
    // Fallback to thumbnailUrl if previewUrl is not available
    if (item.thumbnailUrl) {
      return item.thumbnailUrl;
    }
    
    return '';
  };

  const handleImageLoad = (index) => {
    console.log(`Image ${index} loaded successfully`);
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  const handleImageError = (index, url) => {
    console.error(`Failed to load image ${index}:`, url);
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  // Determine columns based on screen size
  const getColumns = () => {
    if (isMobile) return 2;
    if (isTablet) return 3;
    return 4;
  };

  useEffect(() => {
    fetchAwardsData();
  }, []);

  if (loading) {
    return (
      <Box 
        display="flex" 
        justifyContent="center" 
        alignItems="center" 
        minHeight="200px"
        flexDirection="column"
        gap={2}
      >
        <CircularProgress />
        <Typography variant="body1">Loading awards...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={3} display="flex" flexDirection="column" alignItems="center" gap={2}>
        <Alert severity="error" sx={{ width: '100%', maxWidth: 400 }}>
          {error}
        </Alert>
        <Button 
          variant="contained" 
          startIcon={<Refresh />}
          onClick={fetchAwardsData}
        >
          Try Again
        </Button>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1, sm: 2, md: 3 }, maxWidth: 1200, margin: '0 auto' }}>
      
      {/* Header - Simple and clean like Gallery */}
      <Box textAlign="center" mb={3}>
        <Typography 
          variant="h4" 
          component="h1" 
          gutterBottom
          sx={{ 
            fontWeight: 'bold',
            color: 'primary.main'
          }}
        >
          Our Awards
        </Typography>
        <Typography 
          variant="h6" 
          component="p" 
          color="text.secondary"
          sx={{ mb: 2 }}
        >
          {awardsData.length} {awardsData.length === 1 ? 'award' : 'awards'}
        </Typography>
      </Box>

      {awardsData.length === 0 ? (
        <Box textAlign="center" p={3}>
          <Typography variant="body1" color="text.secondary" gutterBottom>
            No awards found in the gallery.
          </Typography>
          <Button 
            variant="outlined" 
            startIcon={<Refresh />}
            onClick={fetchAwardsData}
            sx={{ mt: 2 }}
          >
            Refresh
          </Button>
        </Box>
      ) : (
        <Box
          sx={{
            columnCount: getColumns(),
            columnGap: 1,
            '& > *': {
              breakInside: 'avoid',
              marginBottom: 1,
              display: 'inline-block',
              width: '100%',
            }
          }}
        >
          {awardsData.map((item, idx) => {
            const imageUrl = getImageUrl(item);
            
            console.log(`Rendering image ${idx}:`, {
              fileName: item.fileName,
              previewUrl: item.previewUrl,
              thumbnailUrl: item.thumbnailUrl,
              finalImageUrl: imageUrl
            });

            return (
              <Box
                key={idx}
                sx={{
                  borderRadius: 2,
                  overflow: 'hidden',
                  boxShadow: 1,
                  transition: 'all 0.3s ease',
                  backgroundColor: 'background.paper',
                  '&:hover': {
                    transform: 'translateY(-4px)',
                    boxShadow: 4,
                  },
                  position: 'relative',
                  display: 'inline-block',
                  width: '100%',
                }}
              >
                {/* Loader - Only show while image is loading */}
                {imageLoadingStates[idx] && (
                  <Box
                    sx={{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      right: 0,
                      bottom: 0,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      backgroundColor: 'rgba(0,0,0,0.05)',
                      zIndex: 1,
                      minHeight: 200,
                    }}
                  >
                    <CircularProgress size={40} />
                  </Box>
                )}
                
                <Box
                  component="img"
                  src={imageUrl}
                  alt={item.fileName}
                  loading="lazy"
                  sx={{
                    width: '100%',
                    height: 'auto',
                    display: 'block',
                    opacity: imageLoadingStates[idx] ? 0 : 1,
                    transition: 'opacity 0.3s ease',
                  }}
                  onLoad={() => handleImageLoad(idx)}
                  onError={() => handleImageError(idx, imageUrl)}
                />

                {/* Description - shown below image */}
                {item.description && (
                  <Box sx={{ p: 1.5 }}>
                    <Typography 
                      variant="body2" 
                      sx={{ 
                        textAlign: 'center',
                        color: 'text.secondary',
                        fontStyle: 'italic',
                        lineHeight: 1.3,
                      }}
                    >
                      {item.description}
                    </Typography>
                  </Box>
                )}
              </Box>
            );
          })}
        </Box>
      )}
    </Box>
  );
};

export default Awards;
